		statement, ok := syntax.StatementOf(parent)
		if !ok {
			return false
		}
		if assignment := syntax.AssignmentStatementOf(statement); assignment != nil {
			for _, left := range assignment.Left {
				if sameExpressionRange(left, current) {
					return true
				}
			}
		}
